// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.connectivity.modelimport com.roshan.persona.connectivity.recording.RecordingPolicy/** * NOUS — Connectivity Config (Module 11 v3 — Step 11.1). * * Configuration for all connectivity engines. * * @see <a href="docs/strategy/module-11-connectivity-strategy-v3.md">§Performance Budgets</a> */data class ConnectivityConfig(    // ─── Contact Search ────────────────────────────────────────────────────    /** Max Levenshtein distance for fuzzy name match (default 3). */    val maxFuzzyDistance: Int = DEFAULT_MAX_FUZZY,    /** Max contacts to return in a search (default 10). */    val maxSearchResults: Int = DEFAULT_MAX_RESULTS,    // ─── Call Engine ───────────────────────────────────────────────────────    /** True if voice verification is required for ALL calls (default true). */    val voiceVerificationRequired: Boolean = true,    /** Contacts in "Trusted" list bypass voice verification (default true). */    val trustedListBypassEnabled: Boolean = true,    /** Emergency numbers that bypass ALL gates. */    val emergencyNumbers: Set<String> = DEFAULT_EMERGENCY_NUMBERS,    /**     * 3-mode Bouncer policy (Strategy §"Active AI Call Screening").     *     * Replaces the legacy binary `autoBlockSpam: Boolean` — see [BouncerMode].     */    val bouncerMode: BouncerMode = BouncerMode.OFF,    /** Active call bouncer enabled (v3 — intercepts unknown calls). */    val activeBouncerEnabled: Boolean = true,    /** Bouncer greeting text. */    val bouncerGreeting: String = "Hello, the person you are calling is using the NOUS AI assistant. Please state the purpose of your call.",    // ─── SMS Engine ────────────────────────────────────────────────────────    /** Max smart reply suggestions (default 3). */    val maxSmartReplies: Int = DEFAULT_MAX_SMART_REPLIES,    /** Smart Payload enabled (v3 — context-aware auto-replies). */    val smartPayloadEnabled: Boolean = true,    /** Auto-reply enabled (calendar/location-aware DND). */    val autoReplyEnabled: Boolean = false,    // ─── Call Recording ────────────────────────────────────────────────────    /** Call recording enabled (opt-in, default false). */    val callRecordingEnabled: Boolean = false,    /** Encryption algorithm for recordings. */    val recordingEncryption: String = "AES-256",    /** Default recording policy for contacts without an explicit setting. */    val defaultRecordingPolicy: RecordingPolicy = RecordingPolicy.ASK,    /** Days after which a recording is auto-deleted (Strategy §11.5: 30). */    val recordingRetentionDays: Int = DEFAULT_RECORDING_RETENTION_DAYS,    // ─── Proactive Comms ───────────────────────────────────────────────────    /** Proactive comms check interval in hours (default 6). */    val proactiveCheckIntervalHours: Int = DEFAULT_PROACTIVE_INTERVAL,    /** Min days since last contact before "neglect alert" (default 14). */    val neglectAlertThresholdDays: Int = DEFAULT_NEGLECT_THRESHOLD,    // ─── SOS ────────────────────────────────────────────────────────────────    /** SOS countdown duration in seconds (v3: 5s cancelable). */    val sosCountdownSeconds: Int = DEFAULT_SOS_COUNTDOWN,    /**     * SOS location update interval in seconds (default 60 — Strategy §11.6     * explicitly specifies 60s, not 30s).     */    val sosLocationUpdateSeconds: Int = DEFAULT_SOS_LOCATION_INTERVAL,    /** SOS location sharing duration in minutes (default 10). */    val sosLocationDurationMinutes: Int = DEFAULT_SOS_LOCATION_DURATION,    /** SOS data auto-delete after hours (default 24). */    val sosDataTtlHours: Int = DEFAULT_SOS_TTL,    // ─── Messaging Unification ─────────────────────────────────────────────    /** Supported messaging apps for unified inbox. */    val supportedMessagingApps: Set<MessagingApp> = setOf(        MessagingApp.SMS,        MessagingApp.WHATSAPP,        MessagingApp.TELEGRAM,    ),    // ─── Comms History ─────────────────────────────────────────────────────    /** Max comms history entries to keep (default 1000). */    val maxHistoryEntries: Int = DEFAULT_MAX_HISTORY,    /** Comms history search result limit (default 50). */    val maxSearchResultsHistory: Int = DEFAULT_MAX_SEARCH_HISTORY,) {    init {        require(maxFuzzyDistance in 1..10) { "maxFuzzyDistance must be 1..10" }        require(maxSearchResults in 1..100) { "maxSearchResults must be 1..100" }        require(maxSmartReplies in 1..10) { "maxSmartReplies must be 1..10" }        require(proactiveCheckIntervalHours in 1..48) { "proactiveCheckIntervalHours must be 1..48" }        require(neglectAlertThresholdDays in 1..90) { "neglectAlertThresholdDays must be 1..90" }        require(sosCountdownSeconds in 0..30) { "sosCountdownSeconds must be 0..30" }        require(sosLocationUpdateSeconds in 5..300) { "sosLocationUpdateSeconds must be 5..300" }        require(sosLocationDurationMinutes in 1..60) { "sosLocationDurationMinutes must be 1..60" }        require(sosDataTtlHours in 1..168) { "sosDataTtlHours must be 1..168" }        require(maxHistoryEntries in 100..10_000) { "maxHistoryEntries must be 100..10000" }        require(emergencyNumbers.isNotEmpty()) { "emergencyNumbers must not be empty" }        require(recordingRetentionDays in 1..365) { "recordingRetentionDays must be 1..365" }    }    companion object {        const val DEFAULT_MAX_FUZZY = 3        const val DEFAULT_MAX_RESULTS = 10        const val DEFAULT_MAX_SMART_REPLIES = 3        const val DEFAULT_PROACTIVE_INTERVAL = 6        const val DEFAULT_NEGLECT_THRESHOLD = 14        const val DEFAULT_SOS_COUNTDOWN = 5        const val DEFAULT_SOS_LOCATION_INTERVAL = 60        const val DEFAULT_SOS_LOCATION_DURATION = 10        const val DEFAULT_SOS_TTL = 24        const val DEFAULT_MAX_HISTORY = 1000        const val DEFAULT_MAX_SEARCH_HISTORY = 50        const val DEFAULT_RECORDING_RETENTION_DAYS = 30        /** Emergency numbers for India + international. */        val DEFAULT_EMERGENCY_NUMBERS = setOf("112", "911", "100", "101", "108", "999")    }}